#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import sys, os, re, io, gzip, json, csv
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from fractions import Fraction

FACTORS = {
    'kg': Fraction(1),
    'g': Fraction(1, 1000),
    'lb': Fraction(45359237, 100000000),
    'oz': Fraction(28349523125, 1000000000000),
}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}


# ---------------------------------------------------------------- bytes/text
def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', errors='replace')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le', errors='replace')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be', errors='replace')
    enc = 'utf-8'
    head = b[:2000].decode('latin-1')
    for line in head.split('\n')[:10]:
        m = re.match(r'\s*#\s*charset\s*:\s*(\S+)', line, re.I)
        if m:
            enc = m.group(1)
            break
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode('utf-8', errors='replace')


# ------------------------------------------------------------------- values
def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def counted(status):
    return status in ('delivered', 'delivered_late')


def parse_number(s, decimal_comma=False):
    s = s.strip().replace(' ', '')
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Fraction(s)


def weight_kg(text, unit, decimal_comma=False):
    """text may carry its own unit suffix."""
    text = (text or '').strip()
    m = re.match(r'^([-+]?[\d.,]+)\s*([A-Za-z]+)$', text)
    if m:
        text, unit = m.group(1), m.group(2).lower()
    unit = (unit or 'kg').lower()
    return parse_number(text, decimal_comma) * FACTORS[unit]


def parse_date(v, form='iso'):
    v = (v or '').strip()
    if not v:
        return None
    f = (form or 'iso').strip().lower().replace('/', '')
    if f == 'serial' and re.fullmatch(r'\d+(\.\d+)?', v):
        return date(1899, 12, 30) + timedelta(days=int(float(v)))
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})', v)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    p = [int(x) for x in re.findall(r'\d+', v)[:3]]
    if len(p) < 3:
        return None
    if re.match(r'^\d{4}\D', v) or f in ('iso', 'ymd', 'yyyymmdd'):
        if re.match(r'^\d{4}\D', v):
            return date(p[0], p[1], p[2])
    if f in ('mmddyyyy',):
        return date(p[2], p[0], p[1])
    if f in ('ddmmyyyy', 'dmy', 'ddmmyyyy'):
        return date(p[2], p[1], p[0])
    if f in ('iso', 'ymd'):
        return date(p[0], p[1], p[2])
    return date(p[0], p[1], p[2])


def parse_time_utc(v):
    v = v.strip()
    d = datetime.fromisoformat(v)
    if d.tzinfo is not None:
        d = d.astimezone(timezone.utc)
    return d.date()


def shipment_number(sid):
    m = re.search(r'(\d+)', str(sid))
    return int(m.group(1)) if m else None


# ------------------------------------------------------------------ records
# record: dict(num, kind in new/corr/void, status, kg (Fraction), day (date))
def mk(sid, kind, status=None, kg=None, day=None):
    n = shipment_number(sid)
    if n is None:
        return None
    return {'num': n, 'kind': kind, 'status': norm_status(status), 'kg': kg, 'day': day}


def parse_delimited(text, depot, delim, quoting, cols, kindmap, wcol, sidcol, kindcol,
                    statcol, datecol, base_date, base_unit, decimal_comma, statmap=None):
    seq = None
    recs = []
    lines = text.split('\n')
    i = 0
    hdr = None
    direct = {}
    while i < len(lines):
        line = lines[i].rstrip('\r')
        i += 1
        if not line.strip():
            continue
        if line.startswith('#'):
            m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*)$', line)
            if m:
                direct[re.sub(r'\s+', ' ', m.group(1).lower())] = m.group(2).strip()
                if m.group(1).strip().lower() == 'seq' and seq is None:
                    try:
                        seq = int(m.group(2).strip())
                    except ValueError:
                        pass
            else:
                m = re.search(r'seq=(\d+)', line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if quoting:
            while line.count('"') % 2 == 1 and i < len(lines):
                line += '\n' + lines[i].rstrip('\r')
                i += 1
            row = next(csv.reader([line], delimiter=delim))
        else:
            row = line.split(delim)
        names = [c.strip().lower() for c in row]
        if names and all(c in cols for c in names):
            hdr = names
            continue
        if hdr is None:
            continue
        unit_extra = None
        if len(row) == len(hdr) + 1 and wcol in hdr:
            k = hdr.index(wcol) + 1
            unit_extra = row[k].strip().lower()
            row = row[:k] + row[k + 1:]
        if len(row) != len(hdr):
            continue
        d = dict(zip(hdr, row))
        sid = d.get(sidcol, '').strip()
        if not re.fullmatch(r'(?i)SH\W*\d+', sid):
            continue
        k = kindmap.get(d.get(kindcol, '').strip().upper() if kindcol else '', 'new') \
            if kindcol else 'new'
        if k == 'void':
            recs.append(mk(sid, 'void'))
            continue
        unit = None
        wtxt = d.get(wcol, '')
        unit = unit_extra
        if unit is None:
            ud = direct.get('unit') or direct.get('weight unit')
            unit = ud.split()[0].lower() if ud else base_unit
        dc = decimal_comma
        form = direct.get('dates') or direct.get('date format') or base_date
        st = d.get(statcol, '')
        if statmap:
            st = statmap.get(st.strip().upper(), st)
        recs.append(mk(sid, k, st, weight_kg(wtxt, unit, dc),
                       parse_date(d.get(datecol, ''), form)))
    return seq, [r for r in recs if r]


KIND_N = {'N': 'new', 'C': 'corr', 'V': 'void', '': 'new', 'NEW': 'new', 'COR': 'corr',
          'VOID': 'void', 'CORR': 'corr'}
HARBOR_ST = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
             'RET': 'returned', 'HLD': 'held'}


def parse_east(t):
    return parse_delimited(t, 'east', ',', True,
                           {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
                           KIND_N, 'gross', 'id', 'type', 'status', 'shipped', 'ymd', 'kg', False)


def parse_lakeside(t):
    km = dict(KIND_N)
    km['CORR'] = 'corr'
    return parse_delimited(t, 'lakeside', ',', True,
                           {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
                           km, 'gross_kg', 'id', 'kind', 'status', 'shipped', 'iso', 'kg', False)


def parse_river(t):
    return parse_delimited(t, 'river', '\t', False,
                           {'t', 'ref', 'shipped', 'weight', 'status'},
                           KIND_N, 'weight', 'ref', 't', 'status', 'shipped',
                           'MM/DD/YYYY', 'kg', False)


def parse_west(t):
    return parse_delimited(t, 'west', ';', False,
                           {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
                           KIND_N, 'weight', 'id', 'typ', 'status', 'shipped',
                           'DMY', 'kg', True)


def parse_harbor(t):
    return parse_delimited(t, 'harbor', '|', False,
                           {'rec', 'ref', 'date', 'weight', 'state'},
                           KIND_N, 'weight', 'ref', 'rec', 'state', 'date',
                           'iso', 'kg', False, statmap=HARBOR_ST)


def parse_north(text):
    seq = None
    recs = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            if 'id' not in o:
                continue
            k = {'new': 'new', 'amend': 'corr', 'void': 'void'}.get(
                str(o.get('kind', 'new')).lower(), 'new')
            if k == 'void':
                recs.append(mk(o['id'], 'void'))
                continue
            kg = None
            for key, val in o.items():
                m = re.fullmatch(r'weight_([a-zA-Z]+)', key)
                if m and val is not None:
                    kg = weight_kg(str(val), m.group(1).lower())
                    break
            recs.append(mk(o['id'], k, o.get('status'), kg,
                           parse_time_utc(o['shipped_at']) if o.get('shipped_at') else None))
    return seq, [r for r in recs if r]


def parse_central(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = root.get('weight-unit', 'kg')
    recs = []
    for s in root.iter('shipment'):
        t = s.get('type', 'new').lower()
        k = {'correction': 'corr', 'void': 'void'}.get(t, 'new')
        sid = s.get('id')
        if k == 'void':
            recs.append(mk(sid, 'void'))
            continue
        w = s.find('weight')
        kg = None
        if w is not None and (w.text or '').strip():
            kg = weight_kg(w.text, w.get('unit') or runit)
        sh = s.get('shipped')
        c = s.find('shipped')
        if c is not None and (c.text or '').strip():
            sh = c.text
        day = None
        if sh:
            sh = sh.strip()
            day = parse_time_utc(sh) if re.match(r'^\d{4}-\d\d-\d\dT', sh) else parse_date(sh)
        st = s.find('status')
        recs.append(mk(sid, k, st.text if st is not None else '', kg, day))
    return seq, [r for r in recs if r]


LAYOUTS = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), ship=(10, 17), w=(17, 25), st=(25, 26),
                sf='yddd', wu=Fraction(1, 1000)),
    'FW2': dict(len=43, type=(0, 1), id=(1, 10), ship=(10, 18), w=(18, 26), st=(26, 27),
                sf='ymd', wu=Fraction(1, 100)),
    'FW3': dict(len=41, id=(0, 9), ship=(9, 16), type=(16, 17), w=(17, 24), st=(24, 25),
                sf='yddd', wu=Fraction(45359237, 100000000) / 10),
}
SOUTH_ST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned',
            'H': 'held'}


def parse_south(text):
    seq = None
    layout = None
    recs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', line)
            if m:
                layout = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not line.strip() or '\f' in line or 'LISTING' in line:
            continue
        L = layout if layout in LAYOUTS and len(line) == LAYOUTS[layout]['len'] else None
        if L is None:
            for n, d in LAYOUTS.items():
                if d['len'] == len(line):
                    L = n
        if L is None:
            continue
        d = LAYOUTS[L]
        f = lambda k: line[d[k][0]:d[k][1]]
        k = {'N': 'new', 'C': 'corr', 'V': 'void'}.get(f('type'))
        if k is None or not re.fullmatch(r'SH\d+', f('id')):
            continue
        if k == 'void':
            recs.append(mk(f('id'), 'void'))
            continue
        sd = f('ship')
        if d['sf'] == 'ymd':
            day = date(int(sd[:4]), int(sd[4:6]), int(sd[6:8]))
        else:
            day = date(int(sd[:4]), 1, 1) + timedelta(days=int(sd[4:]) - 1)
        recs.append(mk(f('id'), k, SOUTH_ST.get(f('st'), f('st')),
                       int(f('w')) * d['wu'], day))
    return seq, [r for r in recs if r]


PARSERS = {'central': parse_central, 'south': parse_south, 'east': parse_east,
           'river': parse_river, 'north': parse_north, 'west': parse_west,
           'harbor': parse_harbor, 'lakeside': parse_lakeside}


def detect_parser(depot, text):
    if depot in PARSERS:
        return PARSERS[depot]
    s = text.lstrip()
    if s.startswith('<'):
        return parse_central
    if s.startswith('{') or s.startswith('['):
        return parse_north
    return None


# --------------------------------------------------------------------- main
def r2(x):
    # x is Fraction; round half up to 2 decimals
    n = x * 100
    q = (n.numerator * 2 + n.denominator) // (n.denominator * 2)
    return q / 100


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        exports.setdefault(depot, [])
        text = read_text(p)
        parser = detect_parser(depot, text)
        if parser is None:
            continue
        seq, recs = parser(text)
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        cur = {}
        for seq, name, recs in sorted(files, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r['num']
                if r['kind'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['kind'] == 'corr':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for n, r in current[depot].items():
            owners.setdefault(n, []).append((depot, r))
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    dep = {d: [0, Fraction(0)] for d in exports}
    mon = {}
    for n, lst in owners.items():
        depot, r = lst[0]
        if not counted(r['status']) or r['kg'] is None or r['day'] is None:
            continue
        dep[depot][0] += 1
        dep[depot][1] += r['kg']
        m = mon.setdefault(r['day'].strftime('%Y-%m'), [0, Fraction(0)])
        m[0] += 1
        m[1] += r['kg']

    out = {
        'depots': {d: {'shipments': v[0], 'total_kg': r2(v[1])} for d, v in sorted(dep.items())},
        'months': {m: {'shipments': v[0], 'total_kg': r2(v[1])} for m, v in sorted(mon.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(out, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
